"""Parcours statistique : thermique classique, Boltzmann, puis modèles avancés."""

def _session(id_, title, status, level, labs, objective, task, success, limits):
    return dict(id=id_, title=title, status=status, level=level, labs=labs.split(),
                objective=objective, task=task, success=success, limits=limits)

def _stage(id_, title, intro, *sessions):
    return dict(id=id_, title=title, intro=intro, sessions=list(sessions))

